INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Wahl der Farben nur eine Frage des Geschmacks?', 2, '[{"text": "Nein", "correct": true, "because": "Sie beeinflusst Lesbarkeit und Marke"}, {"text": "Ja", "correct": false, "because": "Funktionale Aspekte zählen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem einheitlichen Farbschema?', 3, '[{"text": "Konsistenz", "correct": true, "because": "Stärkt die Markenidentität"}, {"text": "Maximale Farbvielfalt", "correct": false, "because": "Kann unruhig wirken"}, {"text": "Technische Effizienz", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind bei der Typografie wichtig?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Erleichtert Textverständnis"}, {"text": "Schriftgröße", "correct": true, "because": "Beeinflusst Zugänglichkeit"}, {"text": "Farbsättigung", "correct": false, "because": "Eher für Farben relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Nicht typografisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Farben können Emotionen wecken. b) Typografie hat keinen Einfluss auf Wahrnehmung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Typografie beeinflusst Lesbarkeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl von Farben für eine App?', 4, '[{"text": "Kontrast", "correct": false, "because": "Wichtig für Lesbarkeit"}, {"text": "Markenrichtlinien", "correct": false, "because": "Sichert Konsistenz"}, {"text": "Serverleistung", "correct": true, "because": "Kein Designfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Schriftart die Ladezeit beeinflusst?', 2, '[{"text": "Ja", "correct": true, "because": "Komplexe Fonts können verzögern"}, {"text": "Nein", "correct": false, "because": "Web-Fonts haben Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Farbe wähle ich für wichtige Buttons?', 3, '[{"text": "Kontrastreiche Farbe", "correct": true, "because": "Hebt sie hervor"}, {"text": "Blasse Farbe", "correct": false, "because": "Wenig sichtbar"}, {"text": "Zufällige Farbe", "correct": false, "because": "Ignoriert Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich für Typografie in einem Dashboard?', 5, '[{"text": "Klarheit", "correct": true, "because": "Erleichtert Datenlesen"}, {"text": "Hierarchie", "correct": true, "because": "Strukturiert Informationen"}, {"text": "Farbanpassung", "correct": false, "because": "Eher für Farben relevant"}, {"text": "Interaktivität", "correct": false, "because": "Nicht typografisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Farben sollten kontrastreich sein. b) Typografie ist nur Dekoration. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Typografie hat Funktion"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Farbwahl für Barrierefreiheit unwichtig?', 4, '[{"text": "Kontrastverhältnis", "correct": false, "because": "Kern der Zugänglichkeit"}, {"text": "Farbblindheit", "correct": false, "because": "Muss berücksichtigt werden"}, {"text": "Persönlicher Geschmack", "correct": true, "because": "Funktion steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sollte ich viele Schriftarten mischen?', 2, '[{"text": "Nein", "correct": true, "because": "Kann unübersichtlich wirken"}, {"text": "Ja", "correct": false, "because": "Konsistenz ist besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Farben eignen sich für eine professionelle Website?', 4, '[{"text": "Neutrale Töne", "correct": true, "because": "Wirken seriös"}, {"text": "Knallige Farben", "correct": false, "because": "Können ablenken"}, {"text": "Zufällige Mischung", "correct": false, "because": "Fehlt Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Typografie keinen Einfluss auf Lesbarkeit hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schriftart und Größe sind entscheidend"}, {"text": "Ja", "correct": false, "because": "Typografie ist funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Typografie für eine App?', 3, '[{"text": "Leserlichkeit", "correct": true, "because": "Nutzer müssen Text verstehen"}, {"text": "Farbsättigung", "correct": false, "because": "Eher für Farben"}, {"text": "Animation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Farben schaffen Markenerkennung. b) Zu viele Farben sind immer gut.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zu viele Farben verwirren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einem Farbschema für ein Formular entscheidend?', 5, '[{"text": "Kontrast für Felder", "correct": true, "because": "Erleichtert Eingabe"}, {"text": "Harmonische Töne", "correct": true, "because": "Verbessert Ästhetik"}, {"text": "Datenfluss", "correct": false, "because": "Nicht Design-relevant"}, {"text": "Backend-Logik", "correct": false, "because": "Technische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Typografie für ein Poster?', 3, '[{"text": "Schriftgröße", "correct": false, "because": "Wichtig für Sichtbarkeit"}, {"text": "Hierarchie", "correct": false, "because": "Strukturiert Inhalte"}, {"text": "Datenbankformat", "correct": true, "because": "Irrelevant für Design"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit Farben? Sollten sie zufällig gewählt werden?', 3, '[{"text": "Nein", "correct": true, "because": "Brauchen Planung für Konsistenz"}, {"text": "Ja", "correct": false, "because": "Zufall wirkt chaotisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Farben die Nutzererfahrung beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Sie lenken Wahrnehmung"}, {"text": "Nein", "correct": false, "because": "Farben sind funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schriftart wähle ich für ein technisches Dokument?', 4, '[{"text": "Sans-Serif", "correct": true, "because": "Klar und modern"}, {"text": "Dekorative Schrift", "correct": false, "because": "Schwer lesbar"}, {"text": "Handschrift", "correct": false, "because": "Unprofessionell"}]');
